15	const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
16	const $ = (sel, el = root) => el.querySelector(sel);
17	const $$ = (sel, el = root) => [...el.querySelectorAll(sel)];
18	const isAluno = () => state.me?.role === 'aluno';
19	const isStaff = () => state.me?.role === 'professor' || state.me?.role === 'admin';
20	const fmt = (n) => Number(n || 0).toLocaleString('pt-BR');
