30	async function api(path, { method = 'GET', body } = {}) {
31	  let res;
32	  try {
33	    res = await fetch(path, {
34	      method,
35	      headers: body ? { 'Content-Type': 'application/json' } : {},
36	      body: body ? JSON.stringify(body) : undefined,
37	      credentials: 'same-origin',
38	    });
39	  } catch {
40	    throw new Error('Sem conexão. Confira sua internet.');
41	  }
42	  let data = {};
43	  try { data = await res.json(); } catch { /* resposta sem JSON */ }
44	  if (res.status === 401 && !path.startsWith('/api/auth')) {
45	    state.me = null;
46	    go('/login');
47	  }
48	  if (!res.ok) throw new Error(data.error || 'Algo deu errado. Tente de novo.');
49	  return data;
50	}
