52	function timeAgo(d) {
53	  const s = Math.max(0, (Date.now() - new Date(d).getTime()) / 1000);
54	  if (s < 60) return 'agora';
55	  if (s < 3600) return `há ${Math.floor(s / 60)} min`;
56	  if (s < 86400) return `há ${Math.floor(s / 3600)} h`;
57	  if (s < 86400 * 7) return `há ${Math.floor(s / 86400)} d`;
58	  return new Date(d).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
59	}
