61	function initials(name) {
62	  const parts = String(name || '?').replace(/^(Profa?\.|Prof\.)\s*/i, '').split(/\s+/)
63	    .map((w) => w.replace(/[^\p{L}\p{N}]/gu, '')).filter(Boolean);
64	  if (!parts.length) return '?';
65	  return ((parts[0]?.[0] || '?') + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase();
66	}
