68	function avatar(id, name, avatarId, size = 40) {
69	  const st = `width:${size}px;height:${size}px;font-size:${Math.round(size * 0.38)}px;`;
70	  if (avatarId) return `<span class="avatar" style="${st}"><img src="/api/img/${avatarId}" alt="" loading="lazy"></span>`;
71	  const h = (Number(id) * 47) % 360;
72	  return `<span class="avatar" style="${st}background:linear-gradient(135deg,hsl(${h} 70% 55%),hsl(${(h + 50) % 360} 75% 48%))">${esc(initials(name))}</span>`;
73	}
