75	function roleBadge(role, guest) {
76	  if (guest) return '<span class="badge banca">Banca</span>';
77	  if (role === 'professor') return '<span class="badge prof">Professor</span>';
78	  if (role === 'admin') return '<span class="badge admin">Oficial</span>';
