82	let toastTimer;
83	function toast(msg) {
84	  let el = document.querySelector('.toast');
85	  if (!el) {
86	    el = document.createElement('div');
87	    el.className = 'toast';
88	    el.setAttribute('role', 'status');
89	    document.body.appendChild(el);
90	  }
91	  el.textContent = msg;
92	  requestAnimationFrame(() => el.classList.add('show'));
93	  clearTimeout(toastTimer);
94	  toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
95	}
