97	// Mostra um "parabéns" quando o aluno desbloqueia troféus.
98	function celebrate(trophies) {
99	  if (!trophies?.length) return;
100	  const queue = [...trophies];
101	  const showNext = () => {
102	    const t = queue.shift();
103	    if (!t) return;
104	    const el = document.createElement('div');
105	    el.className = 'celebrate';
106	    el.innerHTML = `<div class="box">
107	      <div class="emoji">${t.emoji}</div>
108	      <div class="tiny bold muted" style="text-transform:uppercase;letter-spacing:.1em">Troféu desbloqueado!</div>
109	      <h2 style="margin:6px 0">${esc(t.name)}</h2>
110	      <p class="muted" style="margin:0 0 14px">${esc(t.desc)}</p>
111	      <div class="badge" style="font-size:14px;padding:6px 14px;margin-bottom:18px">+${t.points} pontos</div>
112	      <button class="btn primary block">Show! 🎉</button></div>`;
113	    el.addEventListener('click', (e) => {
114	      if (e.target === el || e.target.closest('button')) {
115	        el.remove();
116	        showNext();
117	      }
118	    });
119	    document.body.appendChild(el);
120	  };
121	  showNext();
122	}
