155	// Liga um <form> a uma função assíncrona, travando o botão e mostrando erros.
156	function onSubmit(form, handler) {
157	  form.addEventListener('submit', async (e) => {
158	    e.preventDefault();
159	    const btn = form.querySelector('[type=submit]');
160	    const label = btn?.innerHTML;
161	    if (btn) { btn.disabled = true; btn.innerHTML = 'Aguarde…'; }
162	    try {
163	      await handler(Object.fromEntries(new FormData(form)));
164	    } catch (err) {
165	      toast(err.message);
166	    } finally {
167	      if (btn && btn.isConnected) { btn.disabled = false; btn.innerHTML = label; }
168	    }
169	  });
170	}
