191	  const me = state.me;
192	  const left = back
193	    ? `<button class="icon-btn" data-back aria-label="Voltar">${I.back}</button>`
194	    : '<a href="#/" class="logo" aria-label="Maxx — início">Maxx</a>';
195	  const meBtn = right || (me ? `<a href="#/perfil/${me.id}" aria-label="Meu perfil">${avatar(me.id, me.name, me.avatar_id, 34)}</a>` : '');
196	  const plus = isAluno()
197	    ? `<a href="#/novo" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Publicar foto"><span class="plus-btn">${I.plus}</span></a>`
198	    : `<a href="#/medalha" class="plus ${tab === 'novo' ? 'active' : ''}" aria-label="Dar medalha"><span class="plus-btn">${I.medal}</span></a>`;
199	  const navItem = (key, href, icon, label) => `<a href="${href}" class="${tab === key ? 'active' : ''}">${icon}<span>${label}</span></a>`;
200	  root.className = 'app';
201	  root.innerHTML = `
202	    <header class="topbar">
203	      <div style="min-width:40px">${left}</div>
204	      ${title ? `<div class="title">${esc(title)}</div>` : '<div class="grow"></div>'}
205	      <div style="min-width:40px;display:flex;justify-content:flex-end">${meBtn}</div>
206	    </header>
207	    <main class="view" id="view">${html}</main>
208	    <nav class="bottomnav" aria-label="Menu principal"><div class="inner">
209	      ${navItem('feed', '#/', I.home, 'Feed')}
210	      ${navItem('avisos', '#/avisos', I.mural, 'Avisos')}
211	      ${plus}
212	      ${navItem('ranking', '#/ranking', I.ranking, 'Ranking')}
