225	function shade(hex) {
226	  const n = parseInt(hex.slice(1), 16);
227	  const r = Math.max(0, (n >> 16) - 60), g = Math.max(0, ((n >> 8) & 255) - 60), b = Math.max(0, (n & 255) - 60);
228	  return `rgb(${r},${g},${b})`;
229	}
