231	function postCard(p, { detail = false } = {}) {
232	  const me = state.me;
233	  const canDelete = p.kind === 'foto' && (p.user_id === me.id || me.role === 'admin');
234	  const head = `<div class="post-head row">
235	      <a href="#/perfil/${p.user_id}">${avatar(p.user_id, p.user_name, p.user_avatar, 40)}</a>
236	      <div class="grow">
237	        <div class="ellipsis"><a class="name" href="#/perfil/${p.user_id}">${esc(p.user_name)}</a> ${roleBadge(p.user_role, p.user_guest)}</div>
238	        <div class="tiny muted">${p.user_course ? esc(p.user_course) + ' · ' : ''}${timeAgo(p.created_at)}</div>
239	      </div>
240	      ${canDelete ? `<button class="icon-btn" data-del-post="${p.id}" aria-label="Apagar publicação">${I.trash}</button>` : ''}
241	    </div>`;
242	  let media = '';
243	  if (p.kind === 'foto') {
244	    media = `<div class="post-media" data-dbl="${p.id}">
245	      <img src="/api/img/${p.image_id}" alt="Foto publicada por ${esc(p.user_name)}" loading="lazy">
246	      <div class="heart-pop">❤️</div></div>`;
247	  } else if (p.kind === 'medalha' && p.medal) {
248	    const m = p.medal;
249	    media = `<div class="achv" style="background:linear-gradient(135deg, ${m.color}, ${shade(m.color)})">
250	      <div class="emoji">${m.emoji}</div>
251	      <div class="kicker">Medalha recebida</div>
252	      <div class="what">${esc(m.name)}</div>
253	      ${p.medal_reason ? `<div class="why">“${esc(p.medal_reason)}”</div>` : ''}
254	      <div class="small" style="position:relative;margin-top:6px;opacity:.9">— ${p.prof_id ? `<a href="#/perfil/${p.prof_id}"><b>${esc(p.prof_name)}</b></a>` : 'professor'}</div>
255	      <div class="pts">+${m.points} pontos</div></div>`;
256	  } else if (p.kind === 'trofeu' && p.trophy) {
257	    const t = p.trophy;
258	    media = `<div class="achv tier-${t.tier}">
259	      <div class="emoji">${t.emoji}</div>
260	      <div class="kicker">Troféu desbloqueado</div>
261	      <div class="what">${esc(t.name)}</div>
262	      <div class="why" style="font-style:normal">${esc(t.desc)}</div>
263	      <div class="pts">+${t.points} pontos</div></div>`;
264	  }
265	  const actions = `<div class="post-actions">
266	      <button data-like="${p.id}" class="${p.liked ? 'liked' : ''}" aria-label="Curtir" aria-pressed="${p.liked}">${I.heart}<span data-likes="${p.id}">${fmt(p.likes)}</span></button>
267	      <a href="#/post/${p.id}" class="row" style="padding:8px;gap:6px;font-weight:700" aria-label="Comentários">${I.comment}<span>${fmt(p.comments)}</span></a>
268	    </div>`;
269	  const caption = p.kind === 'foto' && p.caption
270	    ? `<div class="caption"><a href="#/perfil/${p.user_id}" class="bold">${esc(p.user_name)}</a> ${esc(p.caption)}</div>`
271	    : '';
272	  const more = !detail && p.comments > 0
273	    ? `<a href="#/post/${p.id}" class="small muted" style="display:block;margin-top:4px">Ver ${p.comments === 1 ? 'o comentário' : `os ${p.comments} comentários`}</a>`
274	    : '';
275	  return `<article class="card post" data-post="${p.id}">${head}${media}${actions}<div class="post-body">${caption}${more}</div></article>`;
276	}
