381	function bindRoleToggle(form, onChange) {
382	  const box = $('[data-role-toggle]', form);
383	  box.addEventListener('click', (e) => {
384	    const b = e.target.closest('button');
385	    if (!b) return;
386	    $$('button', box).forEach((x) => x.classList.toggle('on', x === b));
387	    form.querySelector('input[name=role]').value = b.dataset.v;
388	    onChange(b.dataset.v);
