483	async function feedScreen() {
484	  const view = layout({ tab: 'feed' }, `
485	    ${bancaWelcome()}
486	    ${isAluno() ? `<div class="chips" style="margin-bottom:12px">
487	      <button class="chip ${state.feedScope === 'all' ? 'on' : ''}" data-scope="all">Toda a UniMax</button>
