// Maxx — app do navegador (sem frameworks, sem etapa de build).
// Cada tela é uma função que monta o HTML e liga os eventos.

const state = {
  me: null,
  config: null,
  bancaCode: '',
  feedScope: 'all',
  rank: { scope: 'geral', period: 'all', course: null },
  achvTab: 'trofeus',
};
const root = document.getElementById('app');

// ---------------------------------------------------------------- utilidades
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const $ = (sel, el = root) => el.querySelector(sel);
const $$ = (sel, el = root) => [...el.querySelectorAll(sel)];
const isAluno = () => state.me?.role === 'aluno';
const isStaff = () => state.me?.role === 'professor' || state.me?.role === 'admin';
const fmt = (n) => Number(n || 0).toLocaleString('pt-BR');

function store(key, value) {
  try {
    if (value === undefined) return localStorage.getItem(key);
    localStorage.setItem(key, value);
  } catch { /* navegador sem armazenamento: tudo bem */ }
  return null;
}

async function api(path, { method = 'GET', body } = {}) {
  let res;
  try {
    res = await fetch(path, {
      method,
      headers: body ? { 'Content-Type': 'application/json' } : {},
      body: body ? JSON.stringify(body) : undefined,
      credentials: 'same-origin',
    });
  } catch {
    throw new Error('Sem conexão. Confira sua internet.');
  }
  let data = {};
  try { data = await res.json(); } catch { /* resposta sem JSON */ }
  if (res.status === 401 && !path.startsWith('/api/auth')) {
    state.me = null;
    go('/login');
  }
  if (!res.ok) throw new Error(data.error || 'Algo deu errado. Tente de novo.');
  return data;
}

function timeAgo(d) {
  const s = Math.max(0, (Date.now() - new Date(d).getTime()) / 1000);
  if (s < 60) return 'agora';
  if (s < 3600) return `há ${Math.floor(s / 60)} min`;
  if (s < 86400) return `há ${Math.floor(s / 3600)} h`;
  if (s < 86400 * 7) return `há ${Math.floor(s / 86400)} d`;
  return new Date(d).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
}

function initials(name) {
  const parts = String(name || '?').replace(/^(Profa?\.|Prof\.)\s*/i, '').split(/\s+/)
    .map((w) => w.replace(/[^\p{L}\p{N}]/gu, '')).filter(Boolean);
  if (!parts.length) return '?';
  return ((parts[0]?.[0] || '?') + (parts.length > 1 ? parts[parts.length - 1][0] : '')).toUpperCase();
}

function avatar(id, name, avatarId, size = 40) {
  const st = `width:${size}px;height:${size}px;font-size:${Math.round(size * 0.38)}px;`;
  if (avatarId) return `<span class="avatar" style="${st}"><img src="/api/img/${avatarId}" alt="" loading="lazy"></span>`;
  const h = (Number(id) * 47) % 360;
  return `<span class="avatar" style="${st}background:linear-gradient(135deg,hsl(${h} 70% 55%),hsl(${(h + 50) % 360} 75% 48%))">${esc(initials(name))}</span>`;
}

function roleBadge(role, guest) {
  if (guest) return '<span class="badge banca">Banca</span>';
  if (role === 'professor') return '<span class="badge prof">Professor</span>';
  if (role === 'admin') return '<span class="badge admin">Oficial</span>';
  return '';
}

let toastTimer;
function toast(msg) {
  let el = document.querySelector('.toast');
  if (!el) {
    el = document.createElement('div');
    el.className = 'toast';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
  }
  el.textContent = msg;
  requestAnimationFrame(() => el.classList.add('show'));
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
}

// Mostra um "parabéns" quando o aluno desbloqueia troféus.
function celebrate(trophies) {
  if (!trophies?.length) return;
  const queue = [...trophies];
  const showNext = () => {
    const t = queue.shift();
    if (!t) return;
    const el = document.createElement('div');
    el.className = 'celebrate';
    el.innerHTML = `<div class="box">
      <div class="emoji">${t.emoji}</div>
      <div class="tiny bold muted" style="text-transform:uppercase;letter-spacing:.1em">Troféu desbloqueado!</div>
      <h2 style="margin:6px 0">${esc(t.name)}</h2>
      <p class="muted" style="margin:0 0 14px">${esc(t.desc)}</p>
      <div class="badge" style="font-size:14px;padding:6px 14px;margin-bottom:18px">+${t.points} pontos</div>
      <button class="btn primary block">Show! 🎉</button></div>`;
    el.addEventListener('click', (e) => {
      if (e.target === el || e.target.closest('button')) {
        el.remove();
        showNext();
      }
    });
    document.body.appendChild(el);
  };
  showNext();
}

function go(path) {
  const target = '#' + path;
  if (location.hash === target) router();
  else location.hash = target;
}

// Diminui a foto no próprio celular antes de enviar (envio rápido, banco leve).
async function resizeImage(file, max = 1080, quality = 0.82) {
  if (!file || !file.type.startsWith('image/')) throw new Error('Escolha um arquivo de imagem.');
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => {
      const i = new Image();
      i.onload = () => resolve(i);
      i.onerror = () => reject(new Error('Não consegui abrir essa imagem. Tente outra (JPG ou PNG).'));
      i.src = url;
    });
    const scale = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.naturalWidth * scale);
    canvas.height = Math.round(img.naturalHeight * scale);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', quality);
  } finally {
    URL.revokeObjectURL(url);
  }
}

// Liga um <form> a uma função assíncrona, travando o botão e mostrando erros.
function onSubmit(form, handler) {
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const btn = form.querySelector('[type=submit]');
    const label = btn?.innerHTML;
    if (btn) { btn.disabled = true; btn.innerHTML = 'Aguarde…'; }
    try {
      await handler(Object.fromEntries(new FormData(form)));
    } catch (err) {
      toast(err.message);
    } finally {
      if (btn && btn.isConnected) { btn.disabled = false; btn.innerHTML = label; }
    }
  });
}

