      <button data-like="${p.id}" class="${p.liked ? 'liked' : ''}" aria-label="Curtir" aria-pressed="${p.liked}">${I.heart}<span data-likes="${p.id}">${fmt(p.likes)}</span></button>
      <a href="#/post/${p.id}" class="row" style="padding:8px;gap:6px;font-weight:700" aria-label="Comentários">${I.comment}<span>${fmt(p.comments)}</span></a>
