    : '';
  return `<article class="card post" data-post="${p.id}">${head}${media}${actions}<div class="post-body">${caption}${more}</div></article>`;
}

async function likePost(id, { onlyLike = false } = {}) {
  const btns = $$(`[data-like="${id}"]`);
  const wasLiked = btns[0]?.classList.contains('liked');
  if (onlyLike && wasLiked) return;
  const apply = (liked, likes) => {
    btns.forEach((b) => { b.classList.toggle('liked', liked); b.setAttribute('aria-pressed', liked); });
    $$(`[data-likes="${id}"]`).forEach((s) => { s.textContent = fmt(likes); });
  };
  const current = Number(($(`[data-likes="${id}"]`)?.textContent || '0').replace(/\D/g, ''));
  apply(!wasLiked, current + (wasLiked ? -1 : 1));
  try {
    const r = await api(`/api/posts/${id}/like`, { method: 'POST' });
    apply(r.liked, r.likes);
  } catch (err) {
    apply(wasLiked, current);
    toast(err.message);
  }
}

// Cliques em qualquer tela (curtir, apagar, voltar, duplo toque na foto).
let lastTap = { id: null, t: 0 };
root.addEventListener('click', async (e) => {
  const back = e.target.closest('[data-back]');
  if (back) {
    if (history.length > 1) history.back();
    else go('/');
    return;
  }
  const like = e.target.closest('[data-like]');
  if (like) return likePost(like.dataset.like);
  const media = e.target.closest('[data-dbl]');
  if (media) {
    const id = media.dataset.dbl;
    const now = Date.now();
    if (lastTap.id === id && now - lastTap.t < 350) {
      const pop = media.querySelector('.heart-pop');
      pop.classList.remove('go');
      void pop.offsetWidth;
      pop.classList.add('go');
      likePost(id, { onlyLike: true });
      lastTap = { id: null, t: 0 };
    } else {
      lastTap = { id, t: now };
    }
    return;
  }
  const del = e.target.closest('[data-del-post]');
  if (del) {
    if (!confirm('Apagar esta publicação? Os pontos dela também saem do ranking.')) return;
    try {
      await api(`/api/posts/${del.dataset.delPost}`, { method: 'DELETE' });
      toast('Publicação apagada.');
      if (location.hash.startsWith('#/post/')) go('/');
      else del.closest('.post')?.remove();
    } catch (err) {
      toast(err.message);
    }
  }
});

