  let cursor = null;
  let loading = false;
  const feed = $('#feed', view);
  const more = $('#more', view);
  const load = async () => {
    if (loading) return;
    loading = true;
    try {
      const qs = new URLSearchParams({ scope: state.feedScope });
      if (cursor) qs.set('before', cursor);
      const r = await api(`/api/feed?${qs}`);
      if (!cursor) feed.innerHTML = '';
      if (!cursor && !r.posts.length) {
        feed.innerHTML = `<div class="empty"><div class="big">📷</div>Nada por aqui ainda.<br>${isAluno() ? 'Que tal publicar a primeira foto?' : ''}</div>`;
      }
      feed.insertAdjacentHTML('beforeend', r.posts.map((p) => postCard(p)).join(''));
      cursor = r.posts.length ? r.posts[r.posts.length - 1].id : cursor;
      more.innerHTML = r.more ? '<button class="btn outline block" id="load-more">Carregar mais</button>' : (r.posts.length ? '<p class="center tiny muted">Você viu tudo ✨</p>' : '');
      const btn = $('#load-more', more);
      if (btn) {
        btn.addEventListener('click', load);
        const io = new IntersectionObserver((entries) => {
          if (entries[0].isIntersecting) { io.disconnect(); load(); }
        }, { rootMargin: '400px' });
        io.observe(btn);
      }
    } catch (err) {
      feed.innerHTML = `<div class="empty">${esc(err.message)}</div>`;
    } finally {
      loading = false;
    }
  };
  load();
}

