async function giveMedalScreen(_m, params) {
  if (!isStaff()) return go('/novo');
  const view = layout({ title: 'Dar medalha', back: true, tab: 'novo' }, `
    <form id="gm" class="stack">
      <div class="section-title" style="margin-top:4px">1. Para qual aluno?</div>
      <input class="input" id="search" placeholder="🔎 Buscar aluno pelo nome" autocomplete="off">
      <div class="card" id="people" style="padding:6px;max-height:280px;overflow:auto"><div class="spinner"></div></div>
      <input type="hidden" name="student_id" value="${esc(params.get('aluno') || '')}">
      <div class="section-title">2. Qual medalha?</div>
      <div class="medal-pick" id="mp">${state.config.medalTypes.map((m) => `
        <button type="button" data-type="${m.code}"><div class="e">${m.emoji}</div><b class="small">${esc(m.name)}</b><div class="tiny muted">+${m.points} pts</div></button>`).join('')}</div>
      <input type="hidden" name="type">
      <p class="hint" id="mdesc" style="margin-top:0"></p>
      <div class="section-title">3. Por quê?</div>
      <textarea class="input" name="reason" maxlength="300" required placeholder="Ex.: Melhor apresentação do seminário de hoje!"></textarea>
      <button class="btn primary block" type="submit">🎖️ Entregar medalha</button>
    </form>`);
  const form = $('#gm', view);
  const sid = form.querySelector('[name=student_id]');
  const people = $('#people', view);
  const renderPeople = (list) => {
    people.innerHTML = list.length ? list.map((u) => `
      <div class="person-pick ${String(u.id) === sid.value ? 'on' : ''}" data-id="${u.id}">
        ${avatar(u.id, u.name, u.avatar_id, 38)}
        <div class="grow"><div class="bold ellipsis">${esc(u.name)} ${roleBadge(u.role, u.is_guest)}</div><div class="tiny muted">${esc(u.course || '')}${u.semester ? ` · ${u.semester}º sem.` : ''}</div></div>
      </div>`).join('') : '<p class="muted small center">Nenhum aluno encontrado.</p>';
  };
  let timer;
  const search = async (term = '') => {
    try {
      const r = await api(`/api/users?role=aluno&q=${encodeURIComponent(term)}`);
      let list = r.users;
      // Garante que o aluno pré-selecionado apareça na lista.
      if (sid.value && !term && !list.some((u) => String(u.id) === sid.value)) {
        const one = await api(`/api/users/${sid.value}`).catch(() => null);
        if (one?.user?.role === 'aluno') list = [{ ...one.user }, ...list];
      }
      if (sid.value && !term) list.sort((a, b) => (String(b.id) === sid.value) - (String(a.id) === sid.value));
      renderPeople(list);
    } catch (err) { people.innerHTML = `<p class="muted small">${esc(err.message)}</p>`; }
  };
  search();
  $('#search', view).addEventListener('input', (e) => { clearTimeout(timer); timer = setTimeout(() => search(e.target.value.trim()), 250); });
  people.addEventListener('click', (e) => {
    const row = e.target.closest('[data-id]');
    if (!row) return;
    sid.value = row.dataset.id;
    $$('.person-pick', people).forEach((x) => x.classList.toggle('on', x === row));
  });
  $('#mp', view).addEventListener('click', (e) => {
    const b = e.target.closest('[data-type]');
    if (!b) return;
    form.querySelector('[name=type]').value = b.dataset.type;
    $$('#mp button', view).forEach((x) => x.classList.toggle('on', x === b));
    $('#mdesc', view).textContent = state.config.medalTypes.find((m) => m.code === b.dataset.type).desc;
  });
  onSubmit(form, async (d) => {
    if (!d.student_id) throw new Error('Escolha o aluno.');
    if (!d.type) throw new Error('Escolha a medalha.');
    const r = await api('/api/medals', { method: 'POST', body: d });
    toast(`Medalha entregue! +${r.points} pts para o aluno 🎖️`);
    go(`/perfil/${d.student_id}`);
  });
}

