async function rankingScreen() {
  const me = state.me;
  const r = state.rank;
  if (r.scope === 'curso' && !r.course) r.course = me.course_id || state.config.courses[0]?.id;
  const view = layout({ title: 'Ranking', tab: 'ranking' }, `
    <div class="segmented" id="scope">
      <button data-v="geral" class="${r.scope === 'geral' ? 'on' : ''}">🌎 Geral</button>
      <button data-v="curso" class="${r.scope === 'curso' ? 'on' : ''}">🎓 Por curso</button>
    </div>
    ${r.scope === 'curso' ? `<div class="chips" style="margin-top:10px" id="courses">${state.config.courses.map((c) => `<button class="chip ${c.id === Number(r.course) ? 'on' : ''}" data-c="${c.id}">${esc(c.short)}</button>`).join('')}</div>` : ''}
    <div class="row" style="justify-content:center;margin-top:10px">
      <div class="segmented" id="period" style="width:240px">
        <button data-v="all" class="${r.period === 'all' ? 'on' : ''}">Sempre</button>
        <button data-v="month" class="${r.period === 'month' ? 'on' : ''}">Este mês</button>
      </div>
    </div>
    <div id="rk"><div class="spinner"></div></div>`);
  $('#scope', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.scope = b.dataset.v; rankingScreen(); } });
  $('#period', view).addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { r.period = b.dataset.v; rankingScreen(); } });
  $('#courses', view)?.addEventListener('click', (e) => { const b = e.target.closest('[data-c]'); if (b) { r.course = Number(b.dataset.c); rankingScreen(); } });
  // Rola o curso escolhido para dentro da tela.
  $('#courses .chip.on', view)?.scrollIntoView({ inline: 'center', block: 'nearest' });

  const qs = new URLSearchParams({ period: r.period });
  if (r.scope === 'curso') qs.set('course', r.course);
  try {
    const { ranking } = await api(`/api/ranking?${qs}`);
    const box = $('#rk', view);
    if (!ranking.length) { box.innerHTML = '<div class="empty"><div class="big">🏁</div>Ninguém nesse ranking ainda.</div>'; return; }
    const top = ranking.slice(0, 3);
    const spot = (u, cls, pos) => u ? `<a class="spot ${cls}" href="#/perfil/${u.id}">
        <div style="display:flex;justify-content:center">${avatar(u.id, u.name, u.avatar_id, pos === 1 ? 70 : 56)}</div>
        <div class="nm">${esc(u.name)}</div><div class="pt">${fmt(u.points)} pts</div>
        <div class="block">${pos === 1 ? '🥇' : pos === 2 ? '🥈' : '🥉'}</div></a>` : '<div></div>';
    const rows = ranking.slice(3).map((u, i) => `
      <a class="rank-row ${u.id === me.id ? 'me' : ''}" href="#/perfil/${u.id}">
        <span class="pos">${i + 4}</span>${avatar(u.id, u.name, u.avatar_id, 38)}
        <div class="grow"><div class="bold ellipsis">${esc(u.name)} ${u.is_guest ? roleBadge('aluno', true) : ''}</div><div class="tiny muted">${esc(u.course || '')}</div></div>
        <span class="pts">${fmt(u.points)}</span></a>`).join('');
    const myPos = ranking.findIndex((u) => u.id === me.id);
    box.innerHTML = `
      <div class="podium">${spot(top[1], 'p2', 2)}${spot(top[0], 'p1', 1)}${spot(top[2], 'p3', 3)}</div>
      ${rows ? `<div class="card" style="overflow:hidden">${rows}</div>` : ''}
      ${myPos >= 0 ? `<div class="card pad me-bar row">
        <b style="font-size:20px">#${myPos + 1}</b>
        <div class="grow"><b>Você</b><div class="tiny muted">de ${ranking.length} ${r.scope === 'curso' ? 'no curso' : 'na UniMax'}</div></div>
        <b>${fmt(ranking[myPos].points)} pts</b></div>` : ''}`;
  } catch (err) { $('#rk', view).innerHTML = `<div class="empty">${esc(err.message)}</div>`; }
}

