function trophyCard(t) {
  const pct = Math.round((t.progress / t.target) * 100);
  return `<div class="card trophy ${t.unlocked ? 'done' : 'locked'}">
    ${t.unlocked ? '' : '<span class="lock">🔒</span>'}
    <div class="ic tier-${t.tier}">${t.emoji}</div>
    <h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p>
    <div class="bar"><i style="width:${t.unlocked ? 100 : pct}%"></i></div>
    <div class="meta"><span>${t.unlocked ? `<span class="ok">✓ ${new Date(t.unlocked_at).toLocaleDateString('pt-BR')}</span>` : `${t.progress}/${t.target}`}</span><span>+${t.points} pts</span></div>
  </div>`;
}

async function achievementsScreen([id]) {
  const me = state.me;
  if (!id && isStaff()) return staffAchievements();
  const userId = Number(id || me.id);
  const own = userId === me.id;
  const view = layout({ title: own ? 'Minhas conquistas' : 'Conquistas', back: !own || Boolean(id), tab: 'conquistas' });
  let d;
  try { d = await api(`/api/achievements/${userId}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const got = d.trophies.filter((t) => t.unlocked).length;
  const medalCount = d.medals.length;
  const typesGot = d.medalTypes.filter((m) => m.count).length;
  const canRevoke = (m) => me.role === 'admin' || m.prof_id === me.id;
  const tabs = {
    trofeus: () => {
      const sorted = [...d.trophies].sort((a, b) => (b.unlocked - a.unlocked) || (b.progress / b.target - a.progress / a.target));
      return `<div class="trophy-grid">${sorted.map(trophyCard).join('')}</div>`;
    },
    medalhas: () => `
      <div class="card" style="overflow:hidden">${d.medalTypes.map((m) => `
        <div class="medal-type row ${m.count ? '' : 'locked'}" style="border-bottom:1px solid var(--line)">
