          <div class="grow"><b>${esc(m.name)}</b> <span class="tiny muted">+${m.points} pts</span><div class="tiny muted">${esc(m.desc)}</div></div>
          ${m.count ? `<span class="badge" style="background:${m.color};color:#fff;font-size:13px">×${m.count}</span>` : '<span class="tiny muted bold">Falta</span>'}
        </div>`).join('')}</div>
