        <div class="card pad row" style="margin-bottom:8px;align-items:flex-start">
          <div style="font-size:30px">${m.medal?.emoji || '🎖️'}</div>
          <div class="grow"><b>${esc(m.medal?.name || m.type)}</b>
            <div class="small">“${esc(m.reason)}”</div>
            <div class="tiny muted">por ${m.prof_id ? `<a href="#/perfil/${m.prof_id}" class="bold">${esc(m.prof_name)}</a>` : 'professor'} · ${timeAgo(m.created_at)}</div></div>
