        <div class="grow"><b>${esc(m.name)}</b> <span class="tiny muted">+${m.points} pts</span><div class="tiny muted">${esc(m.desc)}</div></div>
      </div>`).join('')}</div>
    <div class="section-title">Entregues recentemente</div>
    <div id="given">${given.length ? given.map((m) => `
      <div class="card pad row" style="margin-bottom:8px">
        <a href="#/perfil/${m.student_id}">${avatar(m.student_id, m.student_name, m.student_avatar, 40)}</a>
        <div class="grow"><b class="ellipsis">${m.medal?.emoji || ''} ${esc(m.medal?.name || m.type)}</b> → <a href="#/perfil/${m.student_id}" class="bold">${esc(m.student_name)}</a>
          <div class="tiny muted">“${esc(m.reason)}” · ${timeAgo(m.created_at)}</div></div>
        <button class="btn danger sm" data-revoke="${m.id}">Retirar</button>
      </div>`).join('') : '<div class="empty"><div class="big">🎖️</div>Você ainda não deu nenhuma medalha.</div>'}</div>
    <div class="section-title">Como os alunos pontuam</div>
    <div class="card pad stack">${state.config.pointRules.map((r) => `<div class="row"><span style="font-size:22px">${r.emoji}</span><span class="small">${esc(r.text)}</span></div>`).join('')}</div>`;
  $('#given', view).addEventListener('click', async (e) => {
    const b = e.target.closest('[data-revoke]');
    if (!b || !confirm('Retirar esta medalha? Os pontos dela saem do ranking.')) return;
    try { await api(`/api/medals/${b.dataset.revoke}`, { method: 'DELETE' }); toast('Medalha retirada.'); staffAchievements(); } catch (err) { toast(err.message); }
  });
}

// ---------------------------------------------------------------- tela: perfil
async function profileScreen([id]) {
  const me = state.me;
  const own = Number(id) === me.id;
  const view = layout({
    title: own ? 'Meu perfil' : 'Perfil',
    back: !own,
    right: own ? `<button class="icon-btn" id="logout" aria-label="Sair">${I.logout}</button>` : ' ',
  });
  $('#logout')?.addEventListener('click', logout);
  let d;
  try { d = await api(`/api/users/${id}`); } catch (err) { view.innerHTML = `<div class="empty">${esc(err.message)}</div>`; return; }
  const u = d.user;
  const aluno = u.role === 'aluno';
  let photos = [];
  if (aluno) {
    try { photos = (await api(`/api/feed?user=${u.id}&kind=foto&limit=60`)).posts; } catch { /* sem fotos */ }
  }
  const subtitle = aluno
    ? `${esc(u.course_name || '')}${u.semester ? ` · ${u.semester}º semestre` : ''}`
    : u.role === 'admin' ? 'Perfil oficial da UniMax' : 'Professor(a) da UniMax';
  const pos = d.positions || {};
  const stats = aluno
    ? `<div class="stats">
        <div class="stat hl"><b>${fmt(d.points)}</b><span>pontos</span></div>
        <a class="stat" href="#/ranking" data-rank="geral"><b>${pos.general ? '#' + pos.general : '–'}</b><span>no geral</span></a>
        <a class="stat" href="#/ranking" data-rank="curso"><b>${pos.course ? '#' + pos.course : '–'}</b><span>no curso</span></a>
      </div>`
    : `<div class="stats" style="grid-template-columns:1fr 1fr">
        <div class="stat hl"><b>${fmt(d.medalsGiven)}</b><span>medalhas dadas</span></div>
        <div class="stat"><b>${fmt(d.noticesCount)}</b><span>avisos</span></div>
      </div>`;
  const actions = own
    ? `<div class="row" style="margin-top:14px"><a href="#/editar" class="btn outline grow">Editar perfil</a>${aluno ? '<a href="#/conquistas" class="btn outline grow">Conquistas</a>' : ''}</div>`
    : (aluno && isStaff() ? `<a href="#/medalha?aluno=${u.id}" class="btn primary block" style="margin-top:14px">🎖️ Dar medalha</a>` : '');
  const awards = aluno ? [
    ...d.medals.map((m) => `<div class="trophy-pill"><div class="ic" style="background:${m.color}">${m.emoji}${m.count > 1 ? `<span class="count">×${m.count}</span>` : ''}</div><div class="nm">${esc(m.name)}</div></div>`),
    ...d.trophies.map((t) => `<div class="trophy-pill"><div class="ic tier-${t.tier}">${t.emoji}</div><div class="nm">${esc(t.name)}</div></div>`),
  ] : [];
  view.innerHTML = `
    <div class="card profile-head">
      <div style="display:flex;justify-content:center"><span class="avatar ring" style="width:104px;height:104px"><span>${avatar(u.id, u.name, u.avatar_id, 92)}</span></span></div>
      <h2>${esc(u.name)} ${roleBadge(u.role, u.is_guest)}</h2>
      <div class="small muted" style="margin-top:4px">${subtitle}</div>
      ${u.bio ? `<p class="bio">${esc(u.bio)}</p>` : ''}
      ${stats}${actions}
    </div>
    ${aluno ? `
      <div class="row between"><div class="section-title">Prêmios (${awards.length})</div><a href="#/conquistas/${u.id}" class="small bold" style="color:var(--brand);margin-top:12px">Ver tudo ›</a></div>
      ${awards.length ? `<div class="trophy-strip">${awards.join('')}</div>` : `<p class="muted small" style="margin:4px">${own ? 'Seus troféus e medalhas aparecem aqui. Publique sua primeira foto para começar!' : 'Nenhum prêmio ainda.'}</p>`}
      <div class="section-title">Fotos (${photos.length})</div>
      ${photos.length ? `<div class="grid3">${photos.map((p) => `<a href="#/post/${p.id}"><img src="/api/img/${p.image_id}" alt="" loading="lazy"></a>`).join('')}</div>`
        : `<div class="empty"><div class="big">📷</div>${own ? '<a href="#/novo" class="btn primary">Publicar primeira foto</a>' : 'Nenhuma foto ainda.'}</div>`}` : ''}`;
  $$('[data-rank]', view).forEach((a) => a.addEventListener('click', () => {
    state.rank.scope = a.dataset.rank;
    state.rank.course = u.course_id;
  }));
}

async function logout() {
  if (state.me?.is_guest && !confirm('Sair da conta de visitante? Para voltar, você entra pela banca de novo (com outra conta).')) return;
  await api('/api/auth/logout', { method: 'POST' }).catch(() => {});
  state.me = null;
  go('/login');
}

// ---------------------------------------------------------------- tela: editar perfil
function editProfileScreen() {
  const me = state.me;
  const aluno = me.role === 'aluno';
  const view = layout({ title: 'Editar perfil', back: true }, `
    <form id="ep" class="card pad stack">
      <label style="display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer">
        <span id="av">${avatar(me.id, me.name, me.avatar_id, 96)}</span>
        <span class="small bold" style="color:var(--brand)">Trocar foto de perfil</span>
        <input type="file" accept="image/*" hidden id="avfile">
      </label>
      <label class="field"><span>Nome</span><input class="input" name="name" value="${esc(me.name)}" maxlength="80" required></label>
      <label class="field"><span>Bio</span><textarea class="input" name="bio" maxlength="300" placeholder="Conte um pouco sobre você">${esc(me.bio)}</textarea></label>
      ${aluno ? `
        <label class="field"><span>Curso</span><select class="input" name="course_id">${courseOptions(me.course_id)}</select></label>
        <label class="field"><span>Semestre</span><select class="input" name="semester">${semesterOptions(me.semester)}</select></label>` : ''}
      ${aluno && !me.avatar_id ? '<p class="hint" style="margin:0">🪪 Dica: foto de perfil + bio desbloqueiam o troféu “Cartão de visitas”.</p>' : ''}
      <button class="btn primary block" type="submit">Salvar</button>
    </form>`);
  let avatarData = null;
  $('#avfile', view).addEventListener('change', async (e) => {
    try {
      avatarData = await resizeImage(e.target.files[0], 400, 0.85);
      $('#av', view).innerHTML = `<span class="avatar" style="width:96px;height:96px"><img src="${avatarData}" alt=""></span>`;
    } catch (err) { toast(err.message); }
  });
  onSubmit($('#ep', view), async (d) => {
    const r = await api('/api/me', { method: 'PUT', body: { ...d, avatar: avatarData || undefined } });
    await refreshMe();
    toast('Perfil atualizado!');
    go(`/perfil/${me.id}`);
    celebrate(r.trophies);
  });
}

// ---------------------------------------------------------------- roteador
const routes = [
  [/^\/?$/, feedScreen],
  [/^\/avisos$/, noticesScreen],
  [/^\/novo$/, newPostScreen],
  [/^\/medalha$/, giveMedalScreen],
  [/^\/ranking$/, rankingScreen],
  [/^\/conquistas(?:\/(\d+))?$/, achievementsScreen],
  [/^\/perfil\/(\d+)$/, profileScreen],
  [/^\/editar$/, editProfileScreen],
  [/^\/post\/(\d+)$/, postScreen],
  [/^\/login$/, loginScreen],
  [/^\/cadastro$/, registerScreen],
  [/^\/banca$/, bancaScreen],
];
const PUBLIC = ['/login', '/cadastro', '/banca'];

async function router() {
  const raw = location.hash.slice(1) || '/';
  const [path, qs] = raw.split('?');
  if (!state.me && !PUBLIC.includes(path)) return go('/login');
  if (state.me && PUBLIC.includes(path)) return go('/');
  for (const [re, screen] of routes) {
    const m = path.match(re);
    if (m) {
      window.scrollTo(0, 0);
      try {
        await screen(m.slice(1).filter((x) => x !== undefined), new URLSearchParams(qs || ''));
      } catch (err) {
        console.error(err);
        toast(err.message || 'Erro ao abrir a tela.');
      }
      return;
    }
  }
  go('/');
}

async function boot() {
  const params = new URLSearchParams(location.search);
  if (params.has('banca')) {
    state.bancaCode = params.get('banca') || '';
    history.replaceState(null, '', location.pathname + '#/banca');
  }
  try {
    const [config, me] = await Promise.all([api('/api/config'), api('/api/me')]);
    state.config = config;
    state.me = me.user;
  } catch (err) {
    root.innerHTML = `<div class="empty"><div class="big">📡</div>${esc(err.message)}<br><br><button class="btn primary" onclick="location.reload()">Tentar de novo</button></div>`;
    return;
  }
  window.addEventListener('hashchange', router);
  router();
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
}

boot();

