278	async function likePost(id, { onlyLike = false } = {}) {
279	  const btns = $$(`[data-like="${id}"]`);
280	  const wasLiked = btns[0]?.classList.contains('liked');
281	  if (onlyLike && wasLiked) return;
282	  const apply = (liked, likes) => {
283	    btns.forEach((b) => { b.classList.toggle('liked', liked); b.setAttribute('aria-pressed', liked); });
284	    $$(`[data-likes="${id}"]`).forEach((s) => { s.textContent = fmt(likes); });
285	  };
286	  const current = Number(($(`[data-likes="${id}"]`)?.textContent || '0').replace(/\D/g, ''));
287	  apply(!wasLiked, current + (wasLiked ? -1 : 1));
288	  try {
289	    const r = await api(`/api/posts/${id}/like`, { method: 'POST' });
290	    apply(r.liked, r.likes);
291	  } catch (err) {
292	    apply(wasLiked, current);
293	    toast(err.message);
294	  }
295	}
