298	let lastTap = { id: null, t: 0 };
299	root.addEventListener('click', async (e) => {
300	  const back = e.target.closest('[data-back]');
301	  if (back) {
302	    if (history.length > 1) history.back();
303	    else go('/');
304	    return;
305	  }
306	  const like = e.target.closest('[data-like]');
307	  if (like) return likePost(like.dataset.like);
308	  const media = e.target.closest('[data-dbl]');
309	  if (media) {
310	    const id = media.dataset.dbl;
311	    const now = Date.now();
312	    if (lastTap.id === id && now - lastTap.t < 350) {
313	      const pop = media.querySelector('.heart-pop');
314	      pop.classList.remove('go');
315	      void pop.offsetWidth;
316	      pop.classList.add('go');
317	      likePost(id, { onlyLike: true });
318	      lastTap = { id: null, t: 0 };
319	    } else {
320	      lastTap = { id, t: now };
321	    }
322	    return;
323	  }
324	  const del = e.target.closest('[data-del-post]');
325	  if (del) {
326	    if (!confirm('Apagar esta publicação? Os pontos dela também saem do ranking.')) return;
327	    try {
328	      await api(`/api/posts/${del.dataset.delPost}`, { method: 'DELETE' });
329	      toast('Publicação apagada.');
330	      if (location.hash.startsWith('#/post/')) go('/');
331	      else del.closest('.post')?.remove();
332	    } catch (err) {
333	      toast(err.message);
334	    }
335	  }
336	});
