483	async function feedScreen() {
484	  const view = layout({ tab: 'feed' }, `
485	    ${bancaWelcome()}
486	    ${isAluno() ? `<div class="chips" style="margin-bottom:12px">
487	      <button class="chip ${state.feedScope === 'all' ? 'on' : ''}" data-scope="all">Toda a UniMax</button>
488	      <button class="chip ${state.feedScope === 'course' ? 'on' : ''}" data-scope="course">${esc(state.me.course || 'Meu curso')}</button>
489	    </div>` : ''}
490	    <div id="feed"><div class="spinner"></div></div><div id="more"></div>`);
491	  $('#hide-welcome', view)?.addEventListener('click', () => { store('maxx_hide_welcome', '1'); $('#welcome').remove(); });
492	  $$('[data-scope]', view).forEach((b) => b.addEventListener('click', () => { state.feedScope = b.dataset.scope; feedScreen(); }));
493	
494	  let cursor = null;
495	  let loading = false;
496	  const feed = $('#feed', view);
497	  const more = $('#more', view);
498	  const load = async () => {
499	    if (loading) return;
500	    loading = true;
501	    try {
502	      const qs = new URLSearchParams({ scope: state.feedScope });
503	      if (cursor) qs.set('before', cursor);
504	      const r = await api(`/api/feed?${qs}`);
505	      if (!cursor) feed.innerHTML = '';
506	      if (!cursor && !r.posts.length) {
507	        feed.innerHTML = `<div class="empty"><div class="big">📷</div>Nada por aqui ainda.<br>${isAluno() ? 'Que tal publicar a primeira foto?' : ''}</div>`;
508	      }
509	      feed.insertAdjacentHTML('beforeend', r.posts.map((p) => postCard(p)).join(''));
510	      cursor = r.posts.length ? r.posts[r.posts.length - 1].id : cursor;
511	      more.innerHTML = r.more ? '<button class="btn outline block" id="load-more">Carregar mais</button>' : (r.posts.length ? '<p class="center tiny muted">Você viu tudo ✨</p>' : '');
512	      const btn = $('#load-more', more);
513	      if (btn) {
514	        btn.addEventListener('click', load);
515	        const io = new IntersectionObserver((entries) => {
516	          if (entries[0].isIntersecting) { io.disconnect(); load(); }
517	        }, { rootMargin: '400px' });
518	        io.observe(btn);
519	      }
520	    } catch (err) {
521	      feed.innerHTML = `<div class="empty">${esc(err.message)}</div>`;
522	    } finally {
523	      loading = false;
524	    }
525	  };
526	  load();
527	}
