910	    ...d.medals.map((m) => `<div class="trophy-pill"><div class="ic" style="background:${m.color}">${m.emoji}${m.count > 1 ? `<span class="count">×${m.count}</span>` : ''}</div><div class="nm">${esc(m.name)}</div></div>`),
911	    ...d.trophies.map((t) => `<div class="trophy-pill"><div class="ic tier-${t.tier}">${t.emoji}</div><div class="nm">${esc(t.name)}</div></div>`),
912	  ] : [];
913	  view.innerHTML = `
914	    <div class="card profile-head">
915	      <div style="display:flex;justify-content:center"><span class="avatar ring" style="width:104px;height:104px"><span>${avatar(u.id, u.name, u.avatar_id, 92)}</span></span></div>
916	      <h2>${esc(u.name)} ${roleBadge(u.role, u.is_guest)}</h2>
917	      <div class="small muted" style="margin-top:4px">${subtitle}</div>
918	      ${u.bio ? `<p class="bio">${esc(u.bio)}</p>` : ''}
919	      ${stats}${actions}
920	    </div>
921	    ${aluno ? `
922	      <div class="row between"><div class="section-title">Prêmios (${awards.length})</div><a href="#/conquistas/${u.id}" class="small bold" style="color:var(--brand);margin-top:12px">Ver tudo ›</a></div>
923	      ${awards.length ? `<div class="trophy-strip">${awards.join('')}</div>` : `<p class="muted small" style="margin:4px">${own ? 'Seus troféus e medalhas aparecem aqui. Publique sua primeira foto para começar!' : 'Nenhum prêmio ainda.'}</p>`}
924	      <div class="section-title">Fotos (${photos.length})</div>
925	      ${photos.length ? `<div class="grid3">${photos.map((p) => `<a href="#/post/${p.id}"><img src="/api/img/${p.image_id}" alt="" loading="lazy"></a>`).join('')}</div>`
926	        : `<div class="empty"><div class="big">📷</div>${own ? '<a href="#/novo" class="btn primary">Publicar primeira foto</a>' : 'Nenhuma foto ainda.'}</div>`}` : ''}`;
927	  $$('[data-rank]', view).forEach((a) => a.addEventListener('click', () => {
928	    state.rank.scope = a.dataset.rank;
929	    state.rank.course = u.course_id;
930	  }));
931	}
932	
933	async function logout() {
934	  if (state.me?.is_guest && !confirm('Sair da conta de visitante? Para voltar, você entra pela banca de novo (com outra conta).')) return;
935	  await api('/api/auth/logout', { method: 'POST' }).catch(() => {});
936	  state.me = null;
937	  go('/login');
938	}
939	
940	// ---------------------------------------------------------------- tela: editar perfil
941	function editProfileScreen() {
942	  const me = state.me;
943	  const aluno = me.role === 'aluno';
944	  const view = layout({ title: 'Editar perfil', back: true }, `
945	    <form id="ep" class="card pad stack">
946	      <label style="display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer">
947	        <span id="av">${avatar(me.id, me.name, me.avatar_id, 96)}</span>
948	        <span class="small bold" style="color:var(--brand)">Trocar foto de perfil</span>
949	        <input type="file" accept="image/*" hidden id="avfile">
950	      </label>
951	      <label class="field"><span>Nome</span><input class="input" name="name" value="${esc(me.name)}" maxlength="80" required></label>
952	      <label class="field"><span>Bio</span><textarea class="input" name="bio" maxlength="300" placeholder="Conte um pouco sobre você">${esc(me.bio)}</textarea></label>
953	      ${aluno ? `
954	        <label class="field"><span>Curso</span><select class="input" name="course_id">${courseOptions(me.course_id)}</select></label>
955	        <label class="field"><span>Semestre</span><select class="input" name="semester">${semesterOptions(me.semester)}</select></label>` : ''}
956	      ${aluno && !me.avatar_id ? '<p class="hint" style="margin:0">🪪 Dica: foto de perfil + bio desbloqueiam o troféu “Cartão de visitas”.</p>' : ''}
957	      <button class="btn primary block" type="submit">Salvar</button>
958	    </form>`);
959	  let avatarData = null;
960	  $('#avfile', view).addEventListener('change', async (e) => {
961	    try {
962	      avatarData = await resizeImage(e.target.files[0], 400, 0.85);
963	      $('#av', view).innerHTML = `<span class="avatar" style="width:96px;height:96px"><img src="${avatarData}" alt=""></span>`;
964	    } catch (err) { toast(err.message); }
965	  });
966	  onSubmit($('#ep', view), async (d) => {
967	    const r = await api('/api/me', { method: 'PUT', body: { ...d, avatar: avatarData || undefined } });
968	    await refreshMe();
969	    toast('Perfil atualizado!');
970	    go(`/perfil/${me.id}`);
971	    celebrate(r.trophies);
972	  });
973	}
974	
975	// ---------------------------------------------------------------- roteador
976	const routes = [
977	  [/^\/?$/, feedScreen],
978	  [/^\/avisos$/, noticesScreen],
979	  [/^\/novo$/, newPostScreen],
980	  [/^\/medalha$/, giveMedalScreen],
981	  [/^\/ranking$/, rankingScreen],
982	  [/^\/conquistas(?:\/(\d+))?$/, achievementsScreen],
983	  [/^\/perfil\/(\d+)$/, profileScreen],
984	  [/^\/editar$/, editProfileScreen],
985	  [/^\/post\/(\d+)$/, postScreen],
986	  [/^\/login$/, loginScreen],
987	  [/^\/cadastro$/, registerScreen],
988	  [/^\/banca$/, bancaScreen],
989	];
990	const PUBLIC = ['/login', '/cadastro', '/banca'];
991	
992	async function router() {
993	  const raw = location.hash.slice(1) || '/';
994	  const [path, qs] = raw.split('?');
995	  if (!state.me && !PUBLIC.includes(path)) return go('/login');
996	  if (state.me && PUBLIC.includes(path)) return go('/');
997	  for (const [re, screen] of routes) {
998	    const m = path.match(re);
999	    if (m) {
1000	      window.scrollTo(0, 0);
1001	      try {
1002	        await screen(m.slice(1).filter((x) => x !== undefined), new URLSearchParams(qs || ''));
1003	      } catch (err) {
1004	        console.error(err);
1005	        toast(err.message || 'Erro ao abrir a tela.');
1006	      }
1007	      return;
1008	    }
1009	  }
1010	  go('/');
1011	}
1012	
1013	async function boot() {
1014	  const params = new URLSearchParams(location.search);
1015	  if (params.has('banca')) {
1016	    state.bancaCode = params.get('banca') || '';
1017	    history.replaceState(null, '', location.pathname + '#/banca');
1018	  }
1019	  try {
1020	    const [config, me] = await Promise.all([api('/api/config'), api('/api/me')]);
1021	    state.config = config;
1022	    state.me = me.user;
1023	  } catch (err) {
1024	    root.innerHTML = `<div class="empty"><div class="big">📡</div>${esc(err.message)}<br><br><button class="btn primary" onclick="location.reload()">Tentar de novo</button></div>`;
1025	    return;
1026	  }
1027	  window.addEventListener('hashchange', router);
1028	  router();
1029	  if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
1030	}
1031	
1032	boot();
