244	    res.json(await toggleLike(req.user, int(req.params.id)));
245	  });
246	
247	  app.post('/api/posts/:id/comments', requireUser, async (req, res) => {
248	    res.json(await addComment(req.user, int(req.params.id), req.body.body));
249	  });
250	
251	  app.delete('/api/comments/:id', requireUser, async (req, res) => {
252	    await deleteComment(req.user, int(req.params.id));
253	    res.json({ ok: true });
254	  });
255	
256	  // ---------- Pessoas ----------
257	  app.get('/api/users', requireUser, async (req, res) => {
258	    const term = clean(req.query.q, 60);
259	    const role = req.query.role === 'aluno' ? 'aluno' : null;
260	    const rows = await q(
261	      `SELECT u.id, u.name, u.role, u.avatar_id, u.is_guest, u.semester, c.short AS course
262	         FROM users u LEFT JOIN courses c ON c.id = u.course_id
263	        WHERE ($1::text = '' OR u.name ILIKE '%' || $1 || '%')
264	          AND ($2::text IS NULL OR u.role = $2)
265	        ORDER BY u.name LIMIT 30`,
266	      [term, role],
267	    );
268	    res.json({ users: rows });
269	  });
270	
271	  app.get('/api/users/:id', requireUser, async (req, res) => {
272	    const u = await one(
273	      `SELECT ${PUBLIC_USER_FIELDS}, c.name AS course_name, c.short AS course
274	         FROM users u LEFT JOIN courses c ON c.id = u.course_id WHERE u.id = $1`,
275	      [int(req.params.id)],
276	    );
277	    if (!u) throw new HttpError(404, 'Pessoa não encontrada.');
278	    const out = { user: u };
279	    if (u.role === 'aluno') {
280	      out.points = await totalPoints(u.id);
281	      out.positions = await positions(u);
282	      out.stats = await getStats(u.id);
283	      out.trophies = (await q('SELECT code, unlocked_at FROM user_trophies WHERE user_id = $1 ORDER BY unlocked_at DESC', [u.id]))
284	        .map((t) => ({ ...TROPHY_BY_CODE[t.code], unlocked_at: t.unlocked_at }))
285	        .filter((t) => t.code);
286	      out.medals = (await q('SELECT type, count(*)::int AS n FROM medals WHERE student_id = $1 GROUP BY type', [u.id]))
287	        .map((m) => ({ ...MEDAL_BY_CODE[m.type], count: m.n }))
288	        .filter((m) => m.code);
289	    } else {
290	      const given = await one('SELECT count(*)::int AS n FROM medals WHERE professor_id = $1', [u.id]);
291	      const notices = await one('SELECT count(*)::int AS n FROM notices WHERE author_id = $1', [u.id]);
292	      out.medalsGiven = given.n;
293	      out.noticesCount = notices.n;
294	    }
295	    res.json(out);
296	  });
297	
298	  // ---------- Conquistas ----------
299	  app.get('/api/achievements/:id', requireUser, async (req, res) => {
300	    const u = await one('SELECT id, name, role FROM users WHERE id = $1', [int(req.params.id)]);
301	    if (!u) throw new HttpError(404, 'Pessoa não encontrada.');
302	    if (u.role !== 'aluno') throw new HttpError(400, 'Só alunos têm conquistas.');
303	    const stats = await getStats(u.id);
304	    const unlocked = new Map(
305	      (await q('SELECT code, unlocked_at FROM user_trophies WHERE user_id = $1', [u.id])).map((r) => [r.code, r.unlocked_at]),
306	    );
307	    const trophies = TROPHIES.map((t) => ({
308	      ...t,
309	      progress: Math.min(stats[t.stat] || 0, t.target),
310	      unlocked: unlocked.has(t.code),
311	      unlocked_at: unlocked.get(t.code) || null,
312	    }));
313	    const medals = await q(
314	      `SELECT m.id, m.type, m.reason, m.created_at, pr.id AS prof_id, pr.name AS prof_name
315	         FROM medals m LEFT JOIN users pr ON pr.id = m.professor_id
316	        WHERE m.student_id = $1 ORDER BY m.id DESC`,
317	      [u.id],
318	    );
319	    const counts = {};
320	    for (const m of medals) counts[m.type] = (counts[m.type] || 0) + 1;
321	    res.json({
322	      user: u,
323	      points: await totalPoints(u.id),
324	      trophies,
325	      medalTypes: MEDAL_TYPES.map((m) => ({ ...m, count: counts[m.code] || 0 })),
326	      medals: medals.map((m) => ({ ...m, medal: MEDAL_BY_CODE[m.type] })),
327	      pointRules: POINT_RULES,
328	    });
329	  });
330	
331	  app.post('/api/medals', requireRole('professor', 'admin'), async (req, res) => {
332	    res.json(await giveMedal(req.user, req.body));
333	  });
334	
335	  app.delete('/api/medals/:id', requireRole('professor', 'admin'), async (req, res) => {
336	    await revokeMedal(req.user, int(req.params.id));
337	    res.json({ ok: true });
338	  });
339	
340	  app.get('/api/medals/given', requireRole('professor', 'admin'), async (req, res) => {
341	    const rows = await q(
342	      `SELECT m.id, m.type, m.reason, m.created_at, s.id AS student_id, s.name AS student_name,
343	              s.avatar_id AS student_avatar, c.short AS student_course
344	         FROM medals m JOIN users s ON s.id = m.student_id LEFT JOIN courses c ON c.id = s.course_id
345	        WHERE m.professor_id = $1 ORDER BY m.id DESC LIMIT 100`,
346	      [req.user.id],
347	    );
348	    res.json({ medals: rows.map((m) => ({ ...m, medal: MEDAL_BY_CODE[m.type] })) });
349	  });
350	
351	  // ---------- Ranking ----------
352	  app.get('/api/ranking', requireUser, async (req, res) => {
353	    const courseId = req.query.course ? int(req.query.course) : null;
354	    const period = req.query.period === 'month' ? 'month' : 'all';
355	    const rows = await ranking({ courseId, period });
356	    res.json({ ranking: rows });
357	  });
358	
359	  // ---------- Mural de avisos ----------
360	  app.get('/api/notices', requireUser, async (req, res) => {
361	    const onlyCourse = req.user.role === 'aluno' ? req.user.course_id : null;
362	    const rows = await q(
363	      `SELECT n.id, n.title, n.body, n.pinned, n.created_at, n.course_id, c.short AS course,
364	              u.id AS author_id, u.name AS author_name, u.role AS author_role, u.avatar_id AS author_avatar,
365	              u.is_guest AS author_guest
366	         FROM notices n
367	         LEFT JOIN users u ON u.id = n.author_id
368	         LEFT JOIN courses c ON c.id = n.course_id
369	        WHERE ($1::int IS NULL OR n.course_id IS NULL OR n.course_id = $1)
370	        ORDER BY n.pinned DESC, n.id DESC LIMIT 100`,
371	      [onlyCourse],
372	    );
373	    res.json({ notices: rows });
374	  });
375	
376	  app.post('/api/notices', requireRole('professor', 'admin'), async (req, res) => {
377	    const title = clean(req.body.title, 120);
378	    const body = clean(req.body.body, 3000);
379	    if (!title || !body) throw new HttpError(400, 'Preencha o título e o texto do aviso.');
380	    const courseId = int(req.body.course_id);
381	    const pinned = req.user.role === 'admin' && Boolean(req.body.pinned);
382	    const n = await one(
383	      'INSERT INTO notices (author_id, title, body, course_id, pinned) VALUES ($1, $2, $3, $4, $5) RETURNING id',
384	      [req.user.id, title, body, courseId, pinned],
385	    );
386	    res.json({ id: n.id });
387	  });
388	
389	  app.delete('/api/notices/:id', requireRole('professor', 'admin'), async (req, res) => {
390	    const n = await one('SELECT author_id FROM notices WHERE id = $1', [int(req.params.id)]);
391	    if (!n) throw new HttpError(404, 'Aviso não encontrado.');
392	    if (n.author_id !== req.user.id && req.user.role !== 'admin') throw new HttpError(403, 'Só quem publicou pode apagar.');
393	    await q('DELETE FROM notices WHERE id = $1', [int(req.params.id)]);
394	    res.json({ ok: true });
395	  });
396	
397	  app.use('/api', () => {
398	    throw new HttpError(404, 'Rota não encontrada.');
399	  });
400	
401	  // ---------- App (arquivos estáticos) ----------
402	  app.use(express.static(publicDir, {
403	    setHeaders(res, file) {
404	      if (/\.(html|js|css|webmanifest)$/.test(file) || file.endsWith('sw.js')) res.set('Cache-Control', 'no-cache');
405	    },
406	  }));
407	  app.use((req, res, next) => {
408	    if (req.method !== 'GET') return next();
409	    res.set('Cache-Control', 'no-cache');
410	    res.sendFile(path.join(publicDir, 'index.html'));
411	  });
412	
413	  // ---------- Erros ----------
414	  // eslint-disable-next-line no-unused-vars
415	  app.use((err, _req, res, _next) => {
416	    const status = err.status || err.statusCode || 500;
417	    if (status >= 500) console.error(err);
418	    const message = status === 413 && !(err instanceof HttpError)
419	      ? 'Arquivo grande demais.'
420	      : (err instanceof HttpError || status < 500 ? err.message : 'Erro interno. Tente de novo.');
421	    res.status(status).json({ error: message });
422	  });
423	
424	  return app;
425	}
426	
427	const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
428	if (isMain) {
429	  const app = await createApp();
430	  app.listen(config.port, () => {
431	    console.log(`\n  Maxx rodando em http://localhost:${config.port}`);
432	    console.log(`  Banco: ${dbKind() === 'postgres' ? 'PostgreSQL (DATABASE_URL)' : 'PGlite local (pasta data/)'}`);
433	    if (config.bancaEnabled) {
434	      console.log(`  Link da banca: http://localhost:${config.port}/?banca=${encodeURIComponent(config.bancaCode)}`);
435	    }
436	    console.log('');
437	  });
438	}
